// Records in = records out: one line per email, success or failure.
const items = $input.all();
const outcomes = items.map((it) => (it.json.error
  ? { status: 'FAILED', error: String(it.json.error.message || it.json.error).slice(0, 300) }
  : { status: it.json.outcome || 'UNKNOWN', application_id: it.json.application_id || null }));
return [{ json: { emails: items.length, failed: outcomes.filter((o) => o.status === 'FAILED').length, outcomes } }];

// WF-03 failed before it could dead-letter (e.g. the CRM was down when creating the record):
// keep what we know about the email so it can be re-sent or handled by hand.
const out = [];
$input.all().forEach((it, i) => {
  if (!it.json.error) return;
  const m = $('New email (IMAP)').itemMatching(i).json;
  out.push({ json: { source_workflow: 'WF-03 Email to application', failed_execution_id: $execution.id, stage: 'intake (before CRM record)',
    error: String(it.json.error.message || it.json.error), application: null,
    payload: { message_id: m.messageId || null, from: (m.from && m.from.text) || null, to: (m.to && m.to.text) || null, subject: m.subject || null, date: m.date || null } } });
});
return out;
